void kvm_recalculate_apic_map(struct kvm *kvm) {
    struct kvm_apic_map *new_map;
    int i;

    new_map = kzalloc(sizeof(*new_map), GFP_KERNEL);
    if (!new_map)
        return;

    spin_lock(&kvm->apic_map_lock);

    kvm->apic_map = new_map;
    new_map->max_apic_id = 0;

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        struct kvm_vcpu *vcpu = kvm->vcpus[i];
        struct kvm_lapic *apic;

        if (!vcpu)
            continue;

        apic = vcpu->arch.apic;
        if (!apic)
            continue;

        if (apic->base_address == LAPIC_DEFAULT_BASE_ADDRESS)
            continue;

        new_map->max_apic_id = max(new_map->max_apic_id, apic->apic_id);

        if (apic->x2apic_mode)
            new_map->logical_id_to_apic_id[apic->logical_id] = apic->apic_id;
        else
            new_map->xapic_id_to_apic_id[apic->xapic_id] = apic->apic_id;
    }

    for (i = 0; i < KVM_MAX_APICS; i++) {
        struct kvm_ioapic *ioapic = &kvm->ioapic[i];

        if (!ioapic->base_address)
            continue;

        kvm_ioapic_scan(kvm, ioapic);
    }

    spin_unlock(&kvm->apic_map_lock);
}

void kvm_recalculate_apic_map(struct kvm *kvm) {
    struct kvm_apic_map *new_map;
    struct kvm_vcpu *vcpu;
    int i;

    new_map = kzalloc(sizeof(struct kvm_apic_map), GFP_KERNEL);
    if (!new_map)
        return;

    spin_lock(&kvm->apic_map_lock);

    new_map->nr = 0;
    new_map->max_apic_id = -1;
    new_map->phys_map = NULL;
    new_map->logical_ids = NULL;

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        vcpu = kvm_get_vcpu(kvm, i);
        if (!vcpu)
            continue;

        if (vcpu->apic_base & APIC_MODE_XAPIC) {
            new_map->phys_map[i] = vcpu->apic_id;
            new_map->max_apic_id = max(new_map->max_apic_id, vcpu->apic_id);
        } else {
            new_map->logical_ids[i] = vcpu->apic_id;
        }
        new_map->nr++;
    }

    kvm->arch.apic_map = new_map;
    spin_unlock(&kvm->apic_map_lock);

    kvm_ioapic_scan_all(kvm);
}

void kvm_recalculate_apic_map(struct kvm *kvm)
{
    struct kvm_apic_map *new_map;
    int i;

    new_map = kzalloc(sizeof(struct kvm_apic_apicid) * KVM_APIC_MAP_MAX_APICS, GFP_KERNEL);
    if (!new_map)
        return;

    spin_lock(&kvm->apic_map_lock);

    kvm->apic_map = new_map;
    kvm->nr_apics = 0;

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        struct kvm_vcpu *vcpu = kvm_get_vcpu(kvm, i);
        struct kvm_lapic *apic;

        if (!vcpu)
            continue;

        apic = vcpu->arch.apic;
        if (!apic)
            continue;

        if (apic->base_address & APIC_LVR_SVR) {
            struct kvm_apic_apicid *apicid;

            apicid = &new_map->apicid[kvm->nr_apics];
            apicid->phys_id = apic->phys_id;
            apicid->vcpu = vcpu;

            if (apic->base_address & APIC_LVR_VERSION)
                apicid->x2apic = 1;
            else
                apicid->x2apic = 0;

            kvm->nr_apics++;
        }
    }

    spin_unlock(&kvm->apic_map_lock);

    kvm_free_apic_map(kvm->old_apic_map);
    kvm->old_apic_map = NULL;

    kvm_ioapic_scan_all(kvm);
}

void kvm_recalculate_apic_map(struct kvm *kvm)
{
    struct kvm_apic_map *old_map = kvm->apic_map;
    struct kvm_apic_map *new_map;
    int i;

    new_map = kzalloc(sizeof(*new_map), GFP_KERNEL);
    if (!new_map)
        return;

    spin_lock(&kvm->apic_map_lock);

    kvm->apic_map = new_map;
    new_map->nru = 0;
    new_map->max_apic_id = 0;

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        struct kvm_vcpu *vcpu = kvm->vcpus[i];
        struct kvm_lapic *apic;

        if (!vcpu)
            continue;

        apic = vcpu->arch.apic;
        if (!apic)
            continue;

        if (apic->x2apic_mode)
            new_map->phys_id_2_apic_id[apic->phys_id] = i;
        else
            new_map->phys_id_2_apic_id[apic->phys_id] = -1;

        new_map->max_apic_id = max(new_map->max_apic_id, i);
        new_map->vcpu_map[i] = apic;
    }

    for (i = 0; i <= new_map->max_apic_id; i++) {
        int apic_id = kvm_apic_id(new_map->vcpu_map[i]);
        new_map->logical_id_to_apic_id[apic_id] = i;
    }

    spin_unlock(&kvm->apic_map_lock);

    kfree(old_map);
    kvm_ioapic_scan_all(kvm);
}

void kvm_recalculate_apic_map(struct kvm *kvm) {
    struct kvm_apic_map *new_map;
    struct kvm_vcpu *vcpu;
    int i;

    new_map = kmalloc(sizeof(*new_map), GFP_KERNEL);
    if (!new_map)
        return;

    spin_lock(&kvm->apic_map_lock);
    kvm->apic_map = new_map;
    spin_unlock(&kvm->apic_map_lock);

    for (i = 0; i < KVM_MAX_VCPUS; i++) {
        vcpu = kvm_get_vcpu(kvm, i);
        if (!vcpu)
            continue;

        if (vcpu->arch.apic->base & APIC_XAPIC)
            apic_xapic_config(new_map, vcpu);
        else
            apic_x2apic_config(new_map, vcpu);
    }

    build_logical_id_lookup(new_map, kvm);
    kvm->apic_logical_id_map = new_map->logical_id_map;

    kvm_clean_up_old_apic_map(kvm);
    kvm_request_ioapic_scan(kvm);
}
